t.script:
document.addEventListener("DOMContentLoaded", function () {
    var canvas = document.getElementById("signature_canvas");
    if (!canvas) return;

    var ctx = canvas.getContext("2d");
    var drawing = false;
    var hasSigned = false;

    ctx.lineWidth = 2.5;
    ctx.lineCap = "round";
    ctx.strokeStyle = "#000080";

    function getPos(e) {
        var rect = canvas.getBoundingClientRect();
        var clientX = e.touches ? e.touches[0].clientX : e.clientX;
        var clientY = e.touches ? e.touches[0].clientY : e.clientY;
        return {
            x: clientX - rect.left,
            y: clientY - rect.top
        };
    }

    function startDrawing(e) {
        drawing = true;
        hasSigned = true;
        var pos = getPos(e);
        ctx.beginPath();
        ctx.moveTo(pos.x, pos.y);
    }

    function draw(e) {
        if (!drawing) return;
        e.preventDefault();
        var pos = getPos(e);
        ctx.lineTo(pos.x, pos.y);
        ctx.stroke();
    }

    function stopDrawing() {
        drawing = false;
    }

    canvas.addEventListener("mousedown", startDrawing);
    canvas.addEventListener("mousemove", draw);
    canvas.addEventListener("mouseup", stopDrawing);
    canvas.addEventListener("mouseleave", stopDrawing);

    canvas.addEventListener("touchstart", startDrawing, {passive: false});
    canvas.addEventListener("touchmove", draw, {passive: false});
    canvas.addEventListener("touchend", stopDrawing);

    document.getElementById("clear_signature_btn").addEventListener("click", function () {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        hasSigned = false;
    });

    document.getElementById("agreement_sign_form").addEventListener("submit", function (e) {
        if (!hasSigned) {
            alert("Por favor, firme en el recuadro antes de enviar el convenio.");
            e.preventDefault();
            return false;
        }
        var dataURL = canvas.toDataURL("image/png");
        document.getElementById("signature_data_input").value = dataURL;
    });
});
